# Hypothesis: PEP 695 infers covariance for Reader (T appears only in a return type), so Reader[bool] is accepted as Reader[int]; Cell is invariant because write() takes T, so Cell[bool] and list[bool] are rejected.
from typing import assert_type, reveal_type


class Reader[T]:
    def __init__(self, value: T) -> None:
        self._value = value

    def read(self) -> T:
        return self._value


class Cell[T]:
    def __init__(self, value: T) -> None:
        self._value = value

    def read(self) -> T:
        return self._value

    def write(self, value: T) -> None:
        self._value = value


def read_int(r: Reader[int]) -> int:
    return r.read()


def total(xs: list[int]) -> int:
    return sum(xs)


def set_int(c: Cell[int], v: int) -> int:
    c.write(v)
    return c.read()


def pick[N: (int, str)](a: N, b: N, first: bool) -> N:
    return a if first else b


def bump(c: Cell[int]) -> int:
    return set_int(c, 5)


def reject_bool_list(xs: list[bool]) -> int:
    return total(xs)  # expect-error


flag_reader = Reader(True)
reveal_type(flag_reader)
assert_type(read_int(flag_reader), int)
assert read_int(flag_reader) == 1
assert total([1, 2]) == 3
assert reject_bool_list([True, False]) == 1
assert pick(3, 4, True) == 3
assert pick('a', 'b', False) == 'b'
bool_cell = Cell(False)
assert bump(bool_cell) == 5  # expect-error
